#ifndef KERNEL_H
#define KERNEL_H

#include <ap_fixed.h>
#include <ap_int.h>
#include <stdint.h>

// ── Fixed-point types derived from params.yaml ──────────────────────────────
// acm / eigenvalues: bits=22, signed=1, fraction=0  → ap_fixed<23,23>
// eigenvectors:      bits=22, signed=1, fraction=20 → ap_fixed<23,3>
// max_iter / ite:    bits=16, signed=0, fraction=0  → ap_uint<16>

typedef ap_fixed<23, 23> fx_val_t;      // real/imag for A, eigenvalues
typedef ap_fixed<23,  3> fx_vec_t;      // real/imag for eigenvectors
typedef ap_uint<16>      fx_iter_t;

static const int N = 10;

// Struct for a complex number in the "value" domain (A / eigenvalues)
struct cx_val_t { fx_val_t re, im; };

// Struct for a complex number in the "vector" domain (eigenvectors)
struct cx_vec_t { fx_vec_t re, im; };

// ── Top-level function ───────────────────────────────────────────────────────
void kernel_top(
    cx_val_t     acm[N][N],          // input  A  (10×10 complex)
    fx_iter_t    max_iter,           // input  max_iter
    cx_val_t     eigenvalues[N],     // output eigenvalues (10 complex)
    cx_vec_t     eigenvectors[N][N], // output eigenvectors (10×10 complex)
    fx_iter_t   &ite,                // output iteration count
    uint32_t    &clock_cycles        // C-sim cycle proxy
);

#endif // KERNEL_H
