#include "kernel.h"
#include <hls_math.h>
#include <stdint.h>

// ── Helper: floating-point Jacobi on double arrays, then quantise ───────────
// We keep internal computation in double to avoid fixed-point overflow during
// trigonometric / transcendental operations, then convert back at the end.

static void jacobi_kernel_fp(
    double Ar[N][N], double Ai[N][N],   // in/out: matrix (real & imag)
    double Vr[N][N], double Vi[N][N],   // out   : eigenvectors
    int    max_iter,
    int   &ite_out
)
{
    // Initialise V = I
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            Vr[i][j] = (i == j) ? 1.0 : 0.0;
            Vi[i][j] = 0.0;
        }
    }

    int z = 0;
    for (z = 0; z < max_iter; z++) {
        // ── Find (p,q) with largest |A[i,j]|, i<j ──────────────────────────
        double off_max = 0.0;
        int p = 0, q = 1;
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                double mag = hls::sqrt(Ar[i][j]*Ar[i][j] + Ai[i][j]*Ai[i][j]);
                if (mag > off_max) {
                    off_max = mag;
                    p = i; q = j;
                }
            }
        }

        if (off_max < 1e-8) break;

        // ── Compute Jacobi parameters ────────────────────────────────────────
        double a_pq_r = Ar[p][q], a_pq_i = Ai[p][q];
        double a_pp   = Ar[p][p];        // diagonal elements are real for Hermitian A
        double a_qq   = Ar[q][q];

        double abs_pq = hls::sqrt(a_pq_r*a_pq_r + a_pq_i*a_pq_i);
        double denom  = a_pp - a_qq;

        double theta;
        if (hls::fabs(denom) < 1e-15)
            theta = 3.14159265358979323846 / 4.0;
        else
            theta = 0.5 * hls::atan(2.0 * abs_pq / denom);

        double phi = -hls::atan2(a_pq_i, a_pq_r); // -angle(a_pq)

        double cos_t = hls::cos(theta);
        double sin_t = hls::sin(theta);
        double cos_phi = hls::cos(phi);
        double sin_phi = hls::sin(phi);

        // U[p,p] =  cos(theta)
        // U[p,q] =  sin(theta)*exp(-i*phi) =  sin_t*(cos_phi - i*sin_phi)
        // U[q,p] =  sin(theta)*exp( i*phi) =  sin_t*(cos_phi + i*sin_phi)
        // U[q,q] = -cos(theta)

        double Upr_r =  cos_t;
        double Upr_i =  0.0;
        double Upq_r =  sin_t * cos_phi;
        double Upq_i = -sin_t * sin_phi;
        double Uqp_r =  sin_t * cos_phi;
        double Uqp_i =  sin_t * sin_phi;
        double Uqq_r = -cos_t;
        double Uqq_i =  0.0;

        // ── A' = U†·A·U ──────────────────────────────────────────────────────
        // Step 1: tmp = U† · A   (only rows p and q change)
        double tmpAr[N][N], tmpAi[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                tmpAr[i][j] = Ar[i][j];
                tmpAi[i][j] = Ai[i][j];
            }
        }
        // Row p of tmp:  conj(U[*,p])^T · A  → conj(U[p,p])·A[p,:] + conj(U[q,p])·A[q,:]
        // Row q of tmp:  conj(U[p,q])·A[p,:] + conj(U[q,q])·A[q,:]
        for (int j = 0; j < N; j++) {
            double apr = Ar[p][j], api = Ai[p][j];
            double aqr = Ar[q][j], aqi = Ai[q][j];
            // conj(U[p,p]) = (Upr_r, -Upr_i)
            tmpAr[p][j] = Upr_r*apr + Upr_i*api + Uqp_r*aqr - Uqp_i*aqi; // conj(Uqp)*aq
            tmpAi[p][j] = Upr_r*api - Upr_i*apr + Uqp_r*aqi + Uqp_i*aqr;
            // conj(U[p,q]) = (Upq_r, -Upq_i)
            tmpAr[q][j] = Upq_r*apr - (-Upq_i)*api + Uqq_r*aqr + Uqq_i*aqi;
            tmpAi[q][j] = Upq_r*api + (-Upq_i)*apr + Uqq_r*aqi - Uqq_i*aqr;
        }
        // Fix the signs for conj on row p col term from U[q,p]:
        // We want (conj(U[q,p])) * A[q,j]:
        //   conj(Uqp) = (Uqp_r, -Uqp_i)
        // Let's redo cleanly:
        for (int j = 0; j < N; j++) {
            double apr = Ar[p][j], api = Ai[p][j];
            double aqr = Ar[q][j], aqi = Ai[q][j];

            // new row p = conj(U[p,p])*A[p,j] + conj(U[q,p])*A[q,j]
            double cUpp_r = Upr_r, cUpp_i = -Upr_i;
            double cUqp_r = Uqp_r, cUqp_i = -Uqp_i;
            tmpAr[p][j] = cUpp_r*apr - cUpp_i*api + cUqp_r*aqr - cUqp_i*aqi;
            tmpAi[p][j] = cUpp_r*api + cUpp_i*apr + cUqp_r*aqi + cUqp_i*aqr;

            // new row q = conj(U[p,q])*A[p,j] + conj(U[q,q])*A[q,j]
            double cUpq_r = Upq_r, cUpq_i = -Upq_i;
            double cUqq_r = Uqq_r, cUqq_i = -Uqq_i;
            tmpAr[q][j] = cUpq_r*apr - cUpq_i*api + cUqq_r*aqr - cUqq_i*aqi;
            tmpAi[q][j] = cUpq_r*api + cUpq_i*apr + cUqq_r*aqi + cUqq_i*aqr;
        }

        // Step 2: A'' = tmp · U  (only columns p and q change)
        for (int i = 0; i < N; i++) {
            double tp_r = tmpAr[i][p], tp_i = tmpAi[i][p];
            double tq_r = tmpAr[i][q], tq_i = tmpAi[i][q];

            // col p = tmp[i,p]*U[p,p] + tmp[i,q]*U[q,p]
            Ar[i][p] = tp_r*Upr_r - tp_i*Upr_i + tq_r*Uqp_r - tq_i*Uqp_i;
            Ai[i][p] = tp_r*Upr_i + tp_i*Upr_r + tq_r*Uqp_i + tq_i*Uqp_r;

            // col q = tmp[i,p]*U[p,q] + tmp[i,q]*U[q,q]
            Ar[i][q] = tp_r*Upq_r - tp_i*Upq_i + tq_r*Uqq_r - tq_i*Uqq_i;
            Ai[i][q] = tp_r*Upq_i + tp_i*Upq_r + tq_r*Uqq_i + tq_i*Uqq_r;
        }
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (i != p && i != q) {
                    Ar[i][j] = tmpAr[i][j];
                    Ai[i][j] = tmpAi[i][j];
                }
            }
        }

        // Zero off-diagonal elements explicitly
        Ar[p][q] = 0.0; Ai[p][q] = 0.0;
        Ar[q][p] = 0.0; Ai[q][p] = 0.0;

        // ── V = V · U ────────────────────────────────────────────────────────
        for (int i = 0; i < N; i++) {
            double vp_r = Vr[i][p], vp_i = Vi[i][p];
            double vq_r = Vr[i][q], vq_i = Vi[i][q];

            Vr[i][p] = vp_r*Upr_r - vp_i*Upr_i + vq_r*Uqp_r - vq_i*Uqp_i;
            Vi[i][p] = vp_r*Upr_i + vp_i*Upr_r + vq_r*Uqp_i + vq_i*Uqp_r;

            Vr[i][q] = vp_r*Upq_r - vp_i*Upq_i + vq_r*Uqq_r - vq_i*Uqq_i;
            Vi[i][q] = vp_r*Upq_i + vp_i*Upq_r + vq_r*Uqq_i + vq_i*Uqq_r;
        }
    }

    ite_out = z;
}

// ── Top function ─────────────────────────────────────────────────────────────
void kernel_top(
    cx_val_t     acm[N][N],
    fx_iter_t    max_iter,
    cx_val_t     eigenvalues[N],
    cx_vec_t     eigenvectors[N][N],
    fx_iter_t   &ite,
    uint32_t    &clock_cycles
)
{
#pragma HLS INTERFACE ap_ctrl_hs port=return
#pragma HLS ARRAY_PARTITION variable=acm        complete dim=0
#pragma HLS ARRAY_PARTITION variable=eigenvalues complete dim=1
#pragma HLS ARRAY_PARTITION variable=eigenvectors complete dim=0

    clock_cycles = 0;

    // ── Convert fixed-point inputs to double ──────────────────────────────
    double Ar[N][N], Ai[N][N];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            Ar[i][j] = acm[i][j].re.to_double();
            Ai[i][j] = acm[i][j].im.to_double();
        }
    }

    int mi = (int)max_iter;

    double Vr[N][N], Vi[N][N];
    int z_out = 0;

    jacobi_kernel_fp(Ar, Ai, Vr, Vi, mi, z_out);

    // Count: one "clock" per outer iteration executed
    clock_cycles = (uint32_t)(z_out);

    // ── Pack eigenvalues (diagonal of A) ─────────────────────────────────
    for (int i = 0; i < N; i++) {
        eigenvalues[i].re = (fx_val_t)Ar[i][i];
        eigenvalues[i].im = (fx_val_t)Ai[i][i];
    }

    // ── Pack eigenvectors ─────────────────────────────────────────────────
    EIGVEC_LOOP: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            eigenvectors[i][j].re = (fx_vec_t)Vr[i][j];
            eigenvectors[i][j].im = (fx_vec_t)Vi[i][j];
        }
    }

    ite = (fx_iter_t)z_out;
}
