#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <stdint.h>
#include "kernel.h"

// ── Path constants ────────────────────────────────────────────────────────────
static const char IO_DIR[]  = "/home/mbenton/verilog_rapid_prototyping/conversion_016/eig_10_io/";
static const char SIM_DIR[] = "/home/mbenton/verilog_rapid_prototyping/conversion_016/build/sim/";

// ── Helper: open a file or abort ─────────────────────────────────────────────
static FILE* xfopen(const char* dir, const char* name, const char* mode)
{
    char path[512];
    snprintf(path, sizeof(path), "%s%s", dir, name);
    FILE* f = fopen(path, mode);
    if (!f) {
        fprintf(stderr, "Cannot open: %s\n", path);
        exit(1);
    }
    return f;
}

int main()
{
    // ════════════════════════════════════════════════════════════════════════
    // 1. Read inputs — call index 0 only (first vector in each file)
    // ════════════════════════════════════════════════════════════════════════

    // in_A.txt : 10 rows × 10 cols × (real imag) per element = 100 pairs
    // File holds all 10 captures interleaved; we take the first 100 pairs.
    cx_val_t acm[N][N];
    {
        FILE* f = xfopen(IO_DIR, "in_A.txt", "r");
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                double re, im;
                if (fscanf(f, "%lf %lf", &re, &im) != 2) {
                    fprintf(stderr, "Unexpected EOF in in_A.txt at [%d][%d]\n", i, j);
                    exit(1);
                }
                acm[i][j].re = (fx_val_t)re;
                acm[i][j].im = (fx_val_t)im;
            }
        }
        fclose(f);
    }

    // in_max_iter.txt : one integer per capture; take first line
    fx_iter_t max_iter_val;
    {
        FILE* f = xfopen(IO_DIR, "in_max_iter.txt", "r");
        long long mi;
        if (fscanf(f, "%lld", &mi) != 1) {
            fprintf(stderr, "Unexpected EOF in in_max_iter.txt\n");
            exit(1);
        }
        max_iter_val = (fx_iter_t)mi;
        fclose(f);
    }

    // ════════════════════════════════════════════════════════════════════════
    // 2. Allocate outputs
    // ════════════════════════════════════════════════════════════════════════
    cx_val_t  eigenvalues[N];
    cx_vec_t  eigenvectors[N][N];
    fx_iter_t ite;
    uint32_t  clock_cycles = 0;

    // ════════════════════════════════════════════════════════════════════════
    // 3. Call DUT
    // ════════════════════════════════════════════════════════════════════════
    kernel_top(acm, max_iter_val, eigenvalues, eigenvectors, ite, clock_cycles);

    // ════════════════════════════════════════════════════════════════════════
    // 4. Write outputs
    // ════════════════════════════════════════════════════════════════════════

    // out_0.txt : eigenvalues (10 complex values)
    {
        FILE* f = xfopen(SIM_DIR, "out_0.txt", "w");
        for (int i = 0; i < N; i++) {
            fprintf(f, "%f %f\n",
                    eigenvalues[i].re.to_double(),
                    eigenvalues[i].im.to_double());
        }
        fclose(f);
    }

    // out_1.txt : eigenvectors (10×10 complex)
    {
        FILE* f = xfopen(SIM_DIR, "out_1.txt", "w");
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                fprintf(f, "%f %f\n",
                        eigenvectors[i][j].re.to_double(),
                        eigenvectors[i][j].im.to_double());
            }
        }
        fclose(f);
    }

    // out_2.txt : iteration count (scalar integer)
    {
        FILE* f = xfopen(SIM_DIR, "out_2.txt", "w");
        fprintf(f, "%u\n", (unsigned)ite);
        fclose(f);
    }

    // clock_cycles.txt
    {
        FILE* f = xfopen(SIM_DIR, "clock_cycles.txt", "w");
        fprintf(f, "%u\n", clock_cycles);
        fclose(f);
    }

    printf("kernel_top finished: ite=%u  clock_cycles=%u\n",
           (unsigned)ite, clock_cycles);
    return 0;
}
